// Service worker, registered so push notifications can be added later.
// It does not cache or intercept requests.

self.addEventListener('install', () => {
  self.skipWaiting();
});

self.addEventListener('activate', (event) => {
  event.waitUntil((async () => {
    await self.clients.claim();

    // Clean up after the service worker previously generated by vite-plugin-pwa: drop its
    // precache and reload any windows still showing the stale cached app.
    // ADDED August 2026, REMOVE after a couple months
    const cacheNames = await caches.keys();
    if (cacheNames.length === 0) return;
    await Promise.all(cacheNames.map((cacheName) => caches.delete(cacheName)));

    const windowClients = await self.clients.matchAll({ type: 'window' });
    await Promise.all(windowClients.map((client) => (
      client.navigate(client.url).catch(() => undefined)
    )));
  })());
});
